pub(crate) fn has_property(c: char, mask: u8) -> bool {
    let code = c as u32;
    if code < 48 || code > 210041 { return false; }
    let mut low = 0;
    let mut high = PROPERTIES.len();
    while low < high {
        let mid = low + (high - low) / 2;
        let (start, end, flags) = PROPERTIES[mid];
        if code < start {
            high = mid;
        } else if code > end {
            low = mid + 1;
        } else {
            return flags & mask != 0;
        }
    }
    false
}

