pub(crate) fn has_case_property(c: char, mask: u8) -> bool {
    let code = c as u32;
    if code < 65 || code > 127369 { return false; }
    let mut low = 0;
    let mut high = CASE_PROPERTIES.len();
    while low < high {
        let mid = low + (high - low) / 2;
        let (start, end, flags) = CASE_PROPERTIES[mid];
        if code < start {
            high = mid;
        } else if code > end {
            low = mid + 1;
        } else {
            return flags & mask != 0;
        }
    }
    false
}
